import{_ as a,o as e,c as s,ag as o}from"./chunks/framework.D2veAa-g.js";const b=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-计算机组成-硬盘容量与存取时间","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-计算机组成-硬盘容量与存取时间"},"headers":[],"relativePath":"综合知识/系统基础/计算机组成/硬盘容量与存取时间.md","filePath":"综合知识/系统基础/计算机组成/硬盘容量与存取时间.md","lastUpdated":null}'),n={name:"综合知识/系统基础/计算机组成/硬盘容量与存取时间.md"};function d(l,t,r,i,p,c){return e(),s("div",null,[...t[0]||(t[0]=[o('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 硬盘格式化容量计算</li><li>[x] 硬盘存取时间组成</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="硬盘格式化容量" tabindex="-1">硬盘格式化容量 <a class="header-anchor" href="#硬盘格式化容量" aria-label="Permalink to &quot;硬盘格式化容量&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>格式化容量 = 记录面数 × 每面磁道数 × 每道扇区数 × 每扇区字节数</strong>。</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>格式化容量 = 记录面数 × 磁道数/面 × 扇区数/道 × 字节数/扇区</span></span></code></pre></div><p><strong>计算示例</strong>：</p><blockquote><p>4 个记录面，每面 1000 磁道，每道 200 扇区，每扇区 512 字节</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>容量 = 4 × 1000 × 200 × 512 = 409,600,000 字节 ≈ 400MB</span></span></code></pre></div><p>⚠️ <strong>非格式化容量</strong> ≠ 格式化容量：</p><ul><li>非格式化容量 = 记录面数 × 磁道数 × 内圈周长 × 最大位密度（一般不考）</li><li>格式化后每个扇区会有间隙、同步字段等开销，实际可用容量更小</li></ul><h3 id="硬盘存取时间" tabindex="-1">硬盘存取时间 <a class="header-anchor" href="#硬盘存取时间" aria-label="Permalink to &quot;硬盘存取时间&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>存取时间 = 寻道时间 + 等待时间 + 读/写时间</strong>，其中寻道时间最长，是性能瓶颈。</p></blockquote><table tabindex="0"><thead><tr><th>组成部分</th><th>含义</th><th style="text-align:center;">量级</th></tr></thead><tbody><tr><td><strong>寻道时间</strong></td><td>磁头移动到目标磁道（柱面）的时间</td><td style="text-align:center;">最长（ms 级）</td></tr><tr><td><strong>等待时间</strong>（旋转延迟）</td><td>目标扇区旋转到磁头下方的时间</td><td style="text-align:center;">平均为旋转半圈时间</td></tr><tr><td><strong>读/写时间</strong>（传输时间）</td><td>实际数据读写的时间</td><td style="text-align:center;">相对最短</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>平均存取时间 = 平均寻道时间 + 平均等待时间 + 传输时间</span></span></code></pre></div><blockquote><p>平均等待时间 ≈ 1 / (2 × 转速)，如 7200rpm → 平均等待 ≈ 4.17ms</p></blockquote><h3 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h3><table tabindex="0"><thead><tr><th>易错点</th><th>正解</th></tr></thead><tbody><tr><td>忘了乘记录面数</td><td>硬盘有多个盘面，格式化容量公式第一项就是<strong>记录面数</strong></td></tr><tr><td>存取时间 = 寻道 + 等待</td><td>漏了<strong>读/写（传输）时间</strong>，虽然它最小但不能省略</td></tr><tr><td>MB 换算</td><td>1MB = 10^6 还是 2^20？硬盘厂商用 10^6，考题一般用 1024 进制；注意题干上下文</td></tr></tbody></table>',18)])])}const u=a(n,[["render",d]]);export{b as __pageData,u as default};
